<style>
.en-page
{max-width:1380px;margin:0 auto;color:#17223b
}
.en-heading{display:flex;justify-content:space-between;align-items:center;gap:18px;flex-wrap:wrap;margin-bottom:24px}
.en-eyebrow{font-size:11px;letter-spacing:1.2px;font-weight:800;color:#4f46e5}
.en-heading h2{font-size:26px;margin:6px 0 5px}
.en-heading p,.en-panel-head p{font-size:13px;color:#66738b;margin:5px 0 0}
.en-btn{display:inline-flex;justify-content:center;align-items:center;gap:7px;padding:11px 17px;border:1px solid transparent;border-radius:9px;font-size:13px;font-weight:700;cursor:pointer;white-space:nowrap}.en-primary{background:#4f46e5;color:white}.en-primary:hover{background:#3730a3}.en-outline{background:white;color:#3730a3;border-color:#d9def0}.en-outline:hover{background:#f5f4ff}.en-panel{background:white;border:1px solid #e5eaf3;border-radius:15px;padding:22px;margin-bottom:20px;box-shadow:0 3px 16px #17223b07}.en-panel-head{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:12px;margin-bottom:19px}.en-panel-head h3{font-size:16px;margin:0}.en-count{background:#eef2ff;color:#4338ca;padding:7px 11px;border-radius:20px;font-size:12px;font-weight:800}.en-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.en-field{display:flex;flex-direction:column;gap:7px;min-width:0}.en-field>span{font-size:12px;font-weight:700;color:#42516c}.en-field input,.en-field select{width:100%;min-width:0;min-height:44px;padding:10px 12px;border:1px solid #dbe2ee;border-radius:9px;background:white;color:#17223b;font-size:13px;outline:none}.en-field input:focus,.en-field select:focus{border-color:#6366f1;box-shadow:0 0 0 3px #6366f119}.en-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:19px}.en-table-panel{padding-bottom:12px}.en-scroll{overflow-x:auto;max-width:100%;scrollbar-width:thin}.en-table{width:100%;min-width:1320px;border-collapse:collapse;text-align:left}.en-table th{background:#f4f6fb;color:#52617b;font-size:11px;letter-spacing:.5px;text-transform:uppercase;padding:13px 15px;white-space:nowrap}.en-table td{padding:15px;border-bottom:1px solid #edf0f5;font-size:13px;vertical-align:middle;white-space:nowrap}.en-table tr:last-child td{border-bottom:0}.en-number{font-size:12px;font-weight:800;color:#4338ca;background:#eef2ff;padding:7px 9px;border-radius:7px}.en-person{display:flex;align-items:center;gap:10px}.en-avatar{display:grid;place-items:center;width:36px;height:36px;flex:none;border-radius:10px;background:#e8e9ff;color:#4338ca;font-weight:800}.en-person strong{display:block}.en-person small{display:block;color:#8290a6;margin-top:3px}.en-class{display:inline-flex;background:#f0fdf4;color:#166534;border:1px solid #dcfce7;padding:6px 9px;border-radius:7px;font-weight:700}.en-status{display:inline-flex;border-radius:20px;padding:6px 10px;font-size:11px;font-weight:800}.en-status-enrolled{background:#dcfce7;color:#166534}.en-status-transferred{background:#fef3c7;color:#92400e}.en-status-withdrawn{background:#fee2e2;color:#991b1b}.en-empty{text-align:center;color:#66738b;padding:32px!important}.en-pagination{padding-top:16px;margin-top:8px;border-top:1px solid #edf0f5}.en-form-page{max-width:1050px}.en-form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.en-form-actions{justify-content:flex-end}.en-error{color:#b91c1c;font-size:12px}@media(max-width:1050px){.en-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:640px){.en-grid,.en-form-grid{grid-template-columns:1fr}.en-panel{padding:16px}.en-heading h2{font-size:22px}.en-heading>.en-btn{width:100%}.en-form-actions .en-btn{flex:1}}
</style>
